import Grid from "@mui/material/Grid";

import {
  TimelineRounded,
  TrendingUpRounded,
  CalendarMonthRounded,
  WaterRounded,
} from "@mui/icons-material";

import StatCard from "../../../components/common/StatCard";

import {
  ForecastFilters,
} from "../types/forecast.types";

import {
  useForecastStatistics,
} from "../hooks/useForecast";

import {
  useForecastContext,
} from "../../../contexts/ForecastContext";


const ForecastStatistics = () => {
  const {
    horizon,
    metric,
    entityId,
    scenario,
  } = useForecastContext();


  const filters: ForecastFilters = {
    horizon,
    metric,
    entityId,
    scenario,
  };


  const {
    data,
    isLoading,
    isError,
  } = useForecastStatistics(
    filters
  );


  const formatNumber = (
    value: number
  ): string => {
    return new Intl.NumberFormat(
      "en-US",
      {
        maximumFractionDigits: 2,
      }
    )
      .format(value)
      .replace(/,/g, " ");
  };


  const metricLabel =
    metric === "burn"
      ? "coal burn"
      : metric === "supply"
      ? "coal supply"
      : "stockpile";


  const metricUnit =
    metric === "stockpile"
      ? "tonnes"
      : horizon === "daily"
      ? "t/day"
      : "tonnes";


  const horizonUnit =
    horizon === "daily"
      ? "Days"
      : "Months";


  const cards = [
    {
      title: "Average Forecast",
      value: data
        ? formatNumber(data.average)
        : "...",
      unit: metricUnit,
      subtitle:
        `Average predicted ${metricLabel}`,
      color: "primary" as const,
      icon: <TimelineRounded />,
    },

    {
      title: "Peak Forecast",
      value: data
        ? formatNumber(data.peak)
        : "...",
      unit: metricUnit,
      subtitle:
        `Highest projected ${metricLabel}`,
      color: "warning" as const,
      icon: <TrendingUpRounded />,
    },

    {
      title: "Projected Volume",
      value: data
        ? formatNumber(data.projectedVolume)
        : "...",
      unit: "tonnes",
      subtitle:
        "Forecast horizon total",
      color: "success" as const,
      icon: <WaterRounded />,
    },

    {
      title: "Forecast Horizon",
      value: data
        ? formatNumber(data.horizon)
        : "...",
      unit: horizonUnit,
      subtitle:
        `Current ${entityId} planning period`,
      color: "info" as const,
      icon: <CalendarMonthRounded />,
    },
  ];


  if (isError) {
    return (
      <Grid
        container
        spacing={3}
      >
        <Grid
          item
          xs={12}
        >
          <StatCard
            title="Forecast Statistics"
            value="—"
            unit=""
            subtitle="Unable to load forecast data"
            color="primary"
            icon={
              <TimelineRounded />
            }
          />
        </Grid>
      </Grid>
    );
  }


  return (
    <Grid
      container
      spacing={3}
    >
      {cards.map((card) => (
        <Grid
          item
          xs={12}
          sm={6}
          lg={3}
          key={card.title}
        >
          <StatCard
            title={card.title}
            value={card.value}
            unit={card.unit}
            subtitle={card.subtitle}
            color={card.color}
            icon={card.icon}
          />
        </Grid>
      ))}
    </Grid>
  );
};


export default ForecastStatistics;
